-- Server-only intake. Service role callers must supply a verified Auth UUID.
create table public.seekers (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version>0), auth_user_id uuid not null unique references auth.users(id) on delete cascade);
create table public.providers (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version>0), auth_user_id uuid not null references auth.users(id) on delete cascade, type text not null check(type in ('broker','tenant')), account_status text not null default 'pending' check(account_status in ('pending','approved','suspended')), unique(auth_user_id,type));
create table public.housing_requests (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version>0), seeker_id uuid not null unique references public.seekers(id) on delete cascade, owner_user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'waiting', delete_after timestamptz not null default (now()+interval '90 days'), "situation" text not null check("situation" is null or length("situation") between 1 and 2000) check("situation" in ('입사 예정','근무 중·통근 중','이주 준비','기타')),"date" date,"latest_date" date,"start_date" date,"duration" text check("duration" is null or length("duration") between 1 and 2000),"work_region" text check("work_region" is null or length("work_region") between 1 and 2000),"work_village" text check("work_village" is null or length("work_village") between 1 and 2000),"regions" text[],"any_region" boolean not null,"deposit" integer check("deposit" is null or "deposit" between 0 and 100000),"budget" integer check("budget" is null or "budget" between 0 and 100000),"types" text[],"kitchen" text check("kitchen" is null or length("kitchen") between 1 and 2000),"bath" text check("bath" is null or length("bath") between 1 and 2000),"transport" text check("transport" is null or length("transport") between 1 and 2000),"commute" integer check("commute" is null or "commute" between 0 and 100000),"must" text check("must" is null or length("must") between 1 and 2000),"preferences" text check("preferences" is null or length("preferences") between 1 and 2000), check(latest_date is null or latest_date>=date));
create table public.listings (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1 check(version>0), owner_user_id uuid not null references auth.users(id) on delete cascade, provider_id uuid not null references public.providers(id) on delete restrict, kind text not null check(kind in ('broker','resident','vacancy')), review_status text not null, lifecycle_status text not null default 'open', delete_after timestamptz not null default(now()+interval '90 days'));
create table public.broker_listing_details (listing_id uuid primary key references public.listings(id) on delete cascade, "office" text not null check("office" is null or length("office") between 1 and 2000),"office_number" text not null check("office_number" is null or length("office_number") between 1 and 2000),"representative" text not null check("representative" is null or length("representative") between 1 and 2000),"name" text not null check("name" is null or length("name") between 1 and 2000),"office_address" text not null check("office_address" is null or length("office_address") between 1 and 2000),"office_evidence" text not null check("office_evidence" is null or length("office_evidence") between 1 and 2000),"title" text not null check("title" is null or length("title") between 1 and 2000),"type" text not null check("type" is null or length("type") between 1 and 2000) check("type" in ('셰어하우스','룸메이트','원룸','여유방','하숙')),"building" text not null check("building" is null or length("building") between 1 and 2000),"region" text not null check("region" is null or length("region") between 1 and 2000) check("region" in ('옥천읍','동이면','안남면','안내면','청성면','청산면','이원면','군서면','군북면')),"address" text not null check("address" is null or length("address") between 1 and 2000),"area" text not null check("area" is null or length("area") between 1 and 2000),"floor" text not null check("floor" is null or length("floor") between 1 and 2000),"rooms_baths" text not null check("rooms_baths" is null or length("rooms_baths") between 1 and 2000),"direction" text not null check("direction" is null or length("direction") between 1 and 2000),"approved" date not null,"parking" text not null check("parking" is null or length("parking") between 1 and 2000),"authority" text not null check("authority" is null or length("authority") between 1 and 2000) check("authority" in ('의뢰·안내 동의 확인','추가 확인 필요')),"authority_evidence" text not null check("authority_evidence" is null or length("authority_evidence") between 1 and 2000),"transaction" text not null check("transaction" is null or length("transaction") between 1 and 2000) check("transaction" in ('월세','전세','기타 임대')),"deposit" integer check("deposit" is null or "deposit" between 0 and 100000),"rent" integer check("rent" is null or "rent" between 0 and 100000),"fee" integer check("fee" is null or "fee" between 0 and 100000),"fee_items" text not null check("fee_items" is null or length("fee_items") between 1 and 2000),"fee_basis" text not null check("fee_basis" is null or length("fee_basis") between 1 and 2000),"utilities" text not null check("utilities" is null or length("utilities") between 1 and 2000),"min" integer not null check("min" is null or "min" between 0 and 100000),"max" integer check("max" is null or "max" between 0 and 100000),"commission" text not null check("commission" is null or length("commission") between 1 and 2000),"condition" text not null check("condition" is null or length("condition") between 1 and 2000) check("condition" in ('공실','거주 중·퇴거일 확인','수리 중')),"date" date,"repair_date" date,"facilities" text not null check("facilities" is null or length("facilities") between 1 and 2000),"kitchen" text not null check("kitchen" is null or length("kitchen") between 1 and 2000) check("kitchen" in ('단독','공유','미확인')),"bath" text not null check("bath" is null or length("bath") between 1 and 2000) check("bath" in ('단독','공유','미확인')),"rules" text not null check("rules" is null or length("rules") between 1 and 2000),"inspection" text not null check("inspection" is null or length("inspection") between 1 and 2000),"public_scope" text not null check("public_scope" is null or length("public_scope") between 1 and 2000),"contact_time" text not null check("contact_time" is null or length("contact_time") between 1 and 2000));
create table public.shared_housing_details (listing_id uuid primary key references public.listings(id) on delete cascade, "name" text check("name" is null or length("name") between 1 and 2000),"residency" text not null check("residency" is null or length("residency") between 1 and 2000),"authority" text not null check("authority" is null or length("authority") between 1 and 2000) check("authority" in ('소유자이며 직접 거주','임차인·필요한 동의 확보','동의 확인 중')),"authority_evidence" text not null check("authority_evidence" is null or length("authority_evidence") between 1 and 2000),"type" text not null check("type" is null or length("type") between 1 and 2000) check("type" in ('룸메이트','셰어하우스','하숙','기타 공동거주')),"title" text not null check("title" is null or length("title") between 1 and 2000),"region" text not null check("region" is null or length("region") between 1 and 2000) check("region" in ('옥천읍','동이면','안남면','안내면','청성면','청산면','이원면','군서면','군북면')),"address" text not null check("address" is null or length("address") between 1 and 2000),"current_people" integer not null check("current_people" is null or "current_people" between 0 and 100000),"recruit_people" integer not null check("recruit_people" is null or "recruit_people" between 0 and 100000),"sleeping" text not null check("sleeping" is null or length("sleeping") between 1 and 2000) check("sleeping" in ('개인 방','같은 방 공유')),"room_area" text not null check("room_area" is null or length("room_area") between 1 and 2000),"date" date,"min" integer not null check("min" is null or "min" between 0 and 100000),"end_date" date,"deposit" integer check("deposit" is null or "deposit" between 0 and 100000),"rent" integer check("rent" is null or "rent" between 0 and 100000),"fee" integer check("fee" is null or "fee" between 0 and 100000),"meal" text check("meal" is null or length("meal") between 1 and 2000),"utilities" text not null check("utilities" is null or length("utilities") between 1 and 2000),"kitchen" text not null check("kitchen" is null or length("kitchen") between 1 and 2000) check("kitchen" in ('공유','단독','미확인')),"bath" text not null check("bath" is null or length("bath") between 1 and 2000) check("bath" in ('공유','단독','미확인')),"rules" text not null check("rules" is null or length("rules") between 1 and 2000),"living_rules" text not null check("living_rules" is null or length("living_rules") between 1 and 2000),"intro" text check("intro" is null or length("intro") between 1 and 2000),"contact_time" text not null check("contact_time" is null or length("contact_time") between 1 and 2000));
create table public.vacancy_report_details (listing_id uuid primary key references public.listings(id) on delete cascade, "name" text check("name" is null or length("name") between 1 and 2000),"region" text not null check("region" is null or length("region") between 1 and 2000),"address" text not null check("address" is null or length("address") between 1 and 2000),"type" text not null check("type" is null or length("type") between 1 and 2000),"certainty" text not null check("certainty" is null or length("certainty") between 1 and 2000),"leave_date" date,"timing_note" text check("timing_note" is null or length("timing_note") between 1 and 2000),"contract_end" date,"date_range" text check("date_range" is null or length("date_range") between 1 and 2000),"landlord_notified" text not null check("landlord_notified" is null or length("landlord_notified") between 1 and 2000),"notified_at" date,"notice_method" text check("notice_method" is null or length("notice_method") between 1 and 2000),"landlord_response" text check("landlord_response" is null or length("landlord_response") between 1 and 2000),"planned_notice_at" date,"landlord_intent" text not null check("landlord_intent" is null or length("landlord_intent") between 1 and 2000),"deposit" integer check("deposit" is null or "deposit" between 0 and 100000),"rent" integer check("rent" is null or "rent" between 0 and 100000),"current_fee" text check("current_fee" is null or length("current_fee") between 1 and 2000),"condition_note" text check("condition_note" is null or length("condition_note") between 1 and 2000),"contact_time" text not null check("contact_time" is null or length("contact_time") between 1 and 2000),"current_resident" boolean not null);
create table public.consents (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, housing_request_id uuid references public.housing_requests(id) on delete cascade, listing_id uuid references public.listings(id) on delete cascade, attested_truth boolean not null default false, attested_updates boolean not null default false, purpose text not null check(purpose in ('intake','optional')), policy_version text not null, accepted_at timestamptz not null default now(), check(num_nonnulls(housing_request_id,listing_id)=1));
create table public.applicant_contacts (id uuid primary key default gen_random_uuid(), housing_request_id uuid unique references public.housing_requests(id) on delete cascade, listing_id uuid unique references public.listings(id) on delete cascade, phone_e164 varchar(16) not null check(phone_e164 ~ '^\+82[0-9]{8,10}$'), verification_status text not null default 'unverified' check(verification_status='unverified'), usage_scope text not null default 'operator_only' check(usage_scope='operator_only'), collection_consent_id uuid not null references public.consents(id) on delete cascade, check(num_nonnulls(housing_request_id,listing_id)=1));
create table public.listing_media (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references auth.users(id) on delete cascade, listing_id uuid references public.listings(id) on delete cascade, object_path text not null unique, status text not null default 'uploading' check(status in ('uploading','ready','deleting')), byte_size integer check(byte_size between 1 and 1048576), created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '24 hours'));
create index listing_media_owner on public.listing_media(owner_user_id,created_at);
create index listing_media_listing on public.listing_media(listing_id);
create index listings_owner on public.listings(owner_user_id,created_at);
create index requests_owner on public.housing_requests(owner_user_id);
create table public.idempotency_records (owner_user_id uuid not null references auth.users(id) on delete cascade, operation text not null, key uuid not null, request_hash text not null, result jsonb not null, created_at timestamptz not null default now(), primary key(owner_user_id,operation,key));
alter table public.seekers enable row level security; revoke all on public.seekers from anon,authenticated; grant select,insert,update,delete on public.seekers to service_role;
alter table public.providers enable row level security; revoke all on public.providers from anon,authenticated; grant select,insert,update,delete on public.providers to service_role;
alter table public.housing_requests enable row level security; revoke all on public.housing_requests from anon,authenticated; grant select,insert,update,delete on public.housing_requests to service_role;
alter table public.listings enable row level security; revoke all on public.listings from anon,authenticated; grant select,insert,update,delete on public.listings to service_role;
alter table public.broker_listing_details enable row level security; revoke all on public.broker_listing_details from anon,authenticated; grant select,insert,update,delete on public.broker_listing_details to service_role;
alter table public.shared_housing_details enable row level security; revoke all on public.shared_housing_details from anon,authenticated; grant select,insert,update,delete on public.shared_housing_details to service_role;
alter table public.vacancy_report_details enable row level security; revoke all on public.vacancy_report_details from anon,authenticated; grant select,insert,update,delete on public.vacancy_report_details to service_role;
alter table public.consents enable row level security; revoke all on public.consents from anon,authenticated; grant select,insert,update,delete on public.consents to service_role;
alter table public.applicant_contacts enable row level security; revoke all on public.applicant_contacts from anon,authenticated; grant select,insert,update,delete on public.applicant_contacts to service_role;
alter table public.listing_media enable row level security; revoke all on public.listing_media from anon,authenticated; grant select,insert,update,delete on public.listing_media to service_role;
alter table public.idempotency_records enable row level security; revoke all on public.idempotency_records from anon,authenticated; grant select,insert,update,delete on public.idempotency_records to service_role;
-- INVOKER and service-only: neither caller-controlled role metadata nor phone is authorization.
create function public.save_intake(p_actor uuid,p_kind text,p_key uuid,p_hash text,p_id uuid,p_version integer,p_data jsonb,p_phone text,p_optional boolean,p_media uuid[]) returns jsonb language plpgsql security invoker set search_path='' as $$
declare prior public.idempotency_records; result jsonb; target uuid; provider uuid; seeker uuid; c uuid; tbl text; old_version integer; media_count integer;
begin
 if p_actor is null or p_kind not in ('waiting','broker','resident','vacancy') then raise exception 'INVALID_INPUT'; end if;
 perform 1 from auth.users where id=p_actor; if not found then raise exception 'NOT_AUTHENTICATED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 select * into prior from public.idempotency_records where owner_user_id=p_actor and operation=p_kind and key=p_key;
 if found then if prior.request_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT';end if;return prior.result;end if;
 if (select count(*) from public.idempotency_records where owner_user_id=p_actor and created_at>now()-interval '1 hour')>=30 then raise exception 'RATE_LIMITED';end if;
 if p_kind='waiting' then
 insert into public.seekers(auth_user_id) values(p_actor) on conflict(auth_user_id) do nothing;
 select id into seeker from public.seekers where auth_user_id=p_actor;
 select id,version into target,old_version from public.housing_requests where seeker_id=seeker for update;
 if target is not null and (p_id is null or p_id<>target or p_version<>old_version) then raise exception 'VERSION_CONFLICT';end if;
 if target is null and p_id is not null then raise exception 'NOT_FOUND';end if;
 target:=coalesce(target,gen_random_uuid());
 if old_version is not null then
 update public.housing_requests h set "situation"=r."situation","date"=r."date","latest_date"=r."latest_date","start_date"=r."start_date","duration"=r."duration","work_region"=r."work_region","work_village"=r."work_village","regions"=r."regions","any_region"=r."any_region","deposit"=r."deposit","budget"=r."budget","types"=r."types","kitchen"=r."kitchen","bath"=r."bath","transport"=r."transport","commute"=r."commute","must"=r."must","preferences"=r."preferences",version=h.version+1,updated_at=now() from jsonb_populate_record(null::public.housing_requests,p_data) r where h.id=target;
 else
 insert into public.housing_requests select r.* from jsonb_populate_record(null::public.housing_requests,p_data||jsonb_build_object('id',target,'seeker_id',seeker,'owner_user_id',p_actor,'version',coalesce(old_version,0)+1,'created_at',now(),'updated_at',now(),'status','waiting','delete_after',now()+interval '90 days')) r;
 end if;
 else
 if p_id is not null then
 select id,version into target,old_version from public.listings where id=p_id and owner_user_id=p_actor and kind=p_kind for update;
 if target is null then raise exception 'NOT_FOUND';end if;
 if p_version<>old_version then raise exception 'VERSION_CONFLICT';end if;
 else target:=gen_random_uuid();end if;
 insert into public.providers(auth_user_id,type) values(p_actor,case when p_kind='broker' then 'broker' else 'tenant' end) on conflict(auth_user_id,type) do nothing;
 select id into provider from public.providers where auth_user_id=p_actor and type=case when p_kind='broker' then 'broker' else 'tenant' end and account_status<>'suspended';
 if provider is null then raise exception 'PROVIDER_SUSPENDED';end if;
 if old_version is null then insert into public.listings(id,owner_user_id,provider_id,kind,review_status) values(target,p_actor,provider,p_kind,case when p_kind='broker' then 'not_required' else 'received' end);
 else update public.listings set version=version+1,updated_at=now() where id=target;end if;
 tbl:=case p_kind when 'broker' then 'broker_listing_details' when 'resident' then 'shared_housing_details' else 'vacancy_report_details' end;
 execute format('delete from public.%I where listing_id=$1',tbl) using target;
 execute format('insert into public.%I select r.* from jsonb_populate_record(null::public.%I,$1) r',tbl,tbl) using p_data||jsonb_build_object('listing_id',target);
 select count(*) into media_count from public.listing_media where id=any(p_media) and owner_user_id=p_actor and status='ready' and ((listing_id is null and expires_at>now()) or listing_id=target);
 if cardinality(p_media)>5 or media_count<>cardinality(p_media) or (not p_optional and cardinality(p_media)>0) then raise exception 'INVALID_MEDIA';end if;
 -- Replaced objects remain marked for deletion until the cleanup worker removes Storage objects.
 update public.listing_media set status='deleting' where listing_id=target and not(id=any(p_media));
 update public.listing_media set listing_id=target where id=any(p_media);
 end if;
 insert into public.consents(owner_user_id,housing_request_id,listing_id,purpose,policy_version) values(p_actor,case when p_kind='waiting' then target end,case when p_kind<>'waiting' then target end,'intake','privacy-v1-2026-11-08') returning id into c;
 update public.consents set attested_truth=coalesce((p_data->>'attested_truth')::boolean,false),attested_updates=coalesce((p_data->>'attested_updates')::boolean,false) where id=c;
 if p_optional then insert into public.consents(owner_user_id,housing_request_id,listing_id,purpose,policy_version) values(p_actor,case when p_kind='waiting' then target end,case when p_kind<>'waiting' then target end,'optional','privacy-v1-2026-11-08');end if;
 delete from public.applicant_contacts where housing_request_id=target or listing_id=target;
 insert into public.applicant_contacts(housing_request_id,listing_id,phone_e164,collection_consent_id) values(case when p_kind='waiting' then target end,case when p_kind<>'waiting' then target end,p_phone,c);
 result:=jsonb_build_object('id',target,'kind',p_kind,'version',coalesce(old_version,0)+1);
 insert into public.idempotency_records(owner_user_id,operation,key,request_hash,result) values(p_actor,p_kind,p_key,p_hash,result);
 return result;
end $$;
revoke all on function public.save_intake(uuid,text,uuid,text,uuid,integer,jsonb,text,boolean,uuid[]) from public,anon,authenticated;
grant execute on function public.save_intake(uuid,text,uuid,text,uuid,integer,jsonb,text,boolean,uuid[]) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('listing-photos','listing-photos',false,1048576,array['image/webp']) on conflict(id) do nothing;

create function public.reserve_intake_media(p_actor uuid,p_id uuid,p_path text) returns void language plpgsql security invoker set search_path='' as $$
begin
 if p_actor is null or p_path<>p_actor::text||'/'||p_id::text||'.webp' then raise exception 'INVALID_INPUT';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 if (select count(*) from public.listing_media where owner_user_id=p_actor and (listing_id is null or created_at>now()-interval '1 hour'))>=20 then raise exception 'RATE_LIMITED';end if;
 insert into public.listing_media(id,owner_user_id,object_path) values(p_id,p_actor,p_path);
end $$;
revoke all on function public.reserve_intake_media(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.reserve_intake_media(uuid,uuid,text) to service_role;

-- Keep deletion object paths until Storage deletion succeeds, including retention expiry.
create function public.delete_intake(p_actor uuid,p_kind text,p_id uuid,p_version integer) returns void language plpgsql security invoker set search_path='' as $$
declare current_version integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 if p_kind='waiting' then
 select version into current_version from public.housing_requests where id=p_id and owner_user_id=p_actor for update;
 else
 select version into current_version from public.listings where id=p_id and owner_user_id=p_actor and kind=p_kind for update;
 end if;
 if current_version is null then raise exception 'NOT_FOUND';end if;
 if p_version is null or p_version<>current_version then raise exception 'VERSION_CONFLICT';end if;
 if p_kind='waiting' then delete from public.housing_requests where id=p_id;
 else update public.listing_media set listing_id=null,status='deleting' where listing_id=p_id;delete from public.listings where id=p_id;end if;
 delete from public.idempotency_records where owner_user_id=p_actor and result->>'id'=p_id::text;
end $$;
revoke all on function public.delete_intake(uuid,text,uuid,integer) from public,anon,authenticated;
grant execute on function public.delete_intake(uuid,text,uuid,integer) to service_role;

create index listings_provider on public.listings(provider_id);
create index listings_expiry on public.listings(delete_after);
create index requests_expiry on public.housing_requests(delete_after);
create index consents_listing on public.consents(listing_id);
create index consents_request on public.consents(housing_request_id);
create index consents_owner on public.consents(owner_user_id);
create index contacts_consent on public.applicant_contacts(collection_consent_id);
